package com.tecsup.service; import com.tecsup.client.*; import com.tecsup.dto.*; import com.tecsup.model.Pedido; import com.tecsup.repository.PedidoRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class PedidoService {private final PedidoRepository repo;private final ClienteClient clientes;private final ProductoClient productos;public PedidoService(PedidoRepository r,ClienteClient c,ProductoClient p){repo=r;clientes=c;productos=p;} public Map<String,Object> detalle(Long id){var p=repo.findById(id).orElseThrow(()->new NoSuchElementException("Pedido no encontrado"));var out=new LinkedHashMap<String,Object>();out.put("id",p.getId());out.put("cantidad",p.getCantidad());out.put("estado",p.getEstado());out.put("cliente",clientes.get(p.getClienteId()));out.put("producto",productos.get(p.getProductoId()));return out;} public Pedido crear(Pedido p){clientes.get(p.getClienteId());productos.get(p.getProductoId());return repo.save(p);}}
